import { Microflows, StudioProApi } from "@mendix/extensions-api";
import { ModelDocument } from "../types/modelDocument";

export const handleShowMicroflow = async (studioPro: StudioProApi, modelDocument: ModelDocument): Promise<void> => {
    const microflow = await getMicroflowById(studioPro, modelDocument.documentId);

    if (!microflow) {
        const errorMessage = "Could not find microflow.";
        const errorDetails =
            "This microflow might have been deleted or renamed. Please update the tool microflow selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }

    await studioPro.ui.editors.editDocument(microflow.$ID);
};

export const getMicroflowById = async (
    studioPro: StudioProApi,
    microflowId: string
): Promise<Microflows.Microflow | null> => {
    if (!microflowId) {
        return null;
    }

    try {
        const microflow = await studioPro.app.model.microflows.load<Microflows.Microflow>(
            "Microflows$Microflow",
            microflowId
        );
        return microflow;
    } catch {
        return null;
    }
};
