import { ConsistencyError, StudioProApi } from "@mendix/extensions-api";
import {
    KB_EXCLUDED_ERROR_CODE,
    KB_INVALID_TYPE_ERROR_CODE,
    KB_KEY_NOT_FOUND_ERROR_CODE,
    KB_KEY_REQUIRED_ERROR_CODE,
    KNOWLEDGEBASE_RESERVED_ERROR_CODES,
} from "../../constants/consistencyCodes";
import { ConsistencyCheckResult } from "../../types/generic";
import { Knowledgebase } from "../../types/knowledgebase/knowledgebase";
import { MxCloudGenAIKnowledgebaseFields } from "../../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { getConstantById, isStringConstant } from "../../utils/constantUtils";

export const registerKnowledgebaseConsistencyChecks = (studioPro: StudioProApi) => ({
    check: async (document: Knowledgebase) => {
        const keyResult = await checkKey(studioPro, document);

        return {
            errors: [...keyResult.errors],
            dependentElementIds: [...keyResult.dependentElementIds],
        };
    },
    reservedErrorCodes: KNOWLEDGEBASE_RESERVED_ERROR_CODES,
});

async function checkKey(studioPro: StudioProApi, document: Knowledgebase): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    const providerFields = document.providerFields as MxCloudGenAIKnowledgebaseFields;

    if (!providerFields.key) {
        errors.push({
            errorCode: KB_KEY_REQUIRED_ERROR_CODE,
            errorDescription: "Key is required for a Mendix Cloud knowledge base.",
            severity: "error",
            elementText: "Knowledge base key",
        });
        return { errors, dependentElementIds };
    }

    dependentElementIds.push(providerFields.key.documentId);

    const constant = await getConstantById(studioPro, providerFields.key.documentId);

    if (!constant) {
        errors.push({
            errorCode: KB_KEY_NOT_FOUND_ERROR_CODE,
            errorDescription: `The constant ${providerFields.key.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
            severity: "error",
            elementText: "Knowledge base key",
        });
    } else if (constant.excluded) {
        errors.push({
            errorCode: KB_EXCLUDED_ERROR_CODE,
            errorDescription: `The constant ${providerFields.key.qualifiedName} is excluded from the project and cannot be used.`,
            severity: "error",
            elementText: "Knowledge base key",
        });
    } else if (!isStringConstant(constant)) {
        errors.push({
            errorCode: KB_INVALID_TYPE_ERROR_CODE,
            errorDescription: `The constant ${providerFields.key.qualifiedName} must be of type string.`,
            severity: "error",
            elementText: "Knowledge base key",
        });
    }

    return { errors, dependentElementIds };
}
